let c, sparks=[];
export default {meta:{"id":"motion-particles","name":"Rising sparks","version":"1.0.0","category":"Particles","duration":3,"fps":24,"seekable":false,"keepFrame":false,"thumbnailTime":1,"libs":[],"params":[{"name":"count","label":"How many sparks","type":"number","default":16,"min":4,"max":40,"step":1}]},
init({ctx,params,size,rng}){c=ctx;for(let i=0;i<params.count;i++){sparks.push({x:size.width*(.1+.8*rng()),y:size.height*(.2+.6*rng()),speed:20+30*rng()});}},
renderFrame({dt}){c.fillStyle="#4ddbc5";for(const s of sparks){s.y-=s.speed*dt;c.beginPath();c.arc(s.x,s.y,4,0,Math.PI*2);c.fill();}}};
